:      'This script can be used to feed articles stored in (typical)':      '/h0/SPOOL/RNEWS from a failed rnews operation':      '$Id$':      'Copyright (C) 1990 Ulrich Dessauer, Germering, Germany'::      'Insert here your local configuration':RNEWSDIR=/h0/SPOOL/RNEWS:cd $RNEWSDIRif [ $? -ne 0 ]then  echo "Cannot chdir to $RNEWSDIR, aborted"  exit 1fifor i in *do  if [ "$i" = "*" ]  then    echo "No files in $RNEWSDIR"    exit 0  fi  case X$i in  [0-9]*)    inews < $i    if [ $? -eq 0 ]    then      del $i    else      echo "Article $i could not be fed successfully to inews"    fi    ;;  *)    echo "$i seems not to be a proper file to be feed to inews"    ;;  esacdone